  "check_code": "import hashlib\nimport json\nimport sqlite3\nfrom pathlib import Path\n\nTARGET = \"TASK-250616-044\"\nBASE_TARGET_ACTIVITY_COUNT = 10\nNON_TARGET_TASK_HASH = \"fe315d60558981185c8577280c0f1b490254067ad28d3bb6a5f33f329c445277\"\nNON_TARGET_ACTIVITY_HASH = \"cb27a2ad0628552f018517ed6f245476c70ff3de994ecfd081002fe0c2b745a6\"\nBASE_TARGET_ACTIVITY_ROWS = [\n    (\"ACT-250616-6857\", \"TASK-250616-044\", \"REFILL-20250616-ENDO\", \"STAFF-LI-SHUNING\", \"CREATED\", \"2025-06-16 09:00:58\", None, \"OPEN\", \"审核阻断项转入待办：补录随访结论并确认处方用量\"),\n    (\"ACT-250616-5523\", \"TASK-250616-044\", \"REFILL-20250616-ENDO\", \"STAFF-LI-SHUNING\", \"ASSIGNED\", \"2025-06-16 09:03:56\", \"OPEN\", \"OPEN\", \"按当日排班分派至 CLINICIAN-CHEN-JINGHUI 处理\"),\n    (\"ACT-250616-3349\", \"TASK-250616-044\", \"REFILL-20250616-ENDO\", \"CLINICIAN-ZHOU-NING\", \"COMMENT\", \"2025-06-16 09:21:20\", \"OPEN\", \"OPEN\", \"秘书电话核实患者目前剩余药量；当前关注“补录随访结论并确认处方用量”\"),\n    (\"ACT-250616-4854\", \"TASK-250616-044\", \"REFILL-20250616-ENDO\", \"STAFF-LI-SHUNING\", \"COMMENT\", \"2025-06-16 10:32:11\", \"OPEN\", \"OPEN\", \"用药频次与患者自述记录完成交叉核对；当前关注“补录随访结论并确认处方用量”\"),\n    (\"ACT-250616-2232\", \"TASK-250616-044\", \"REFILL-20250616-ENDO\", \"CLINICIAN-CHEN-JINGHUI\", \"COMMENT\", \"2025-06-16 13:33:32\", \"OPEN\", \"OPEN\", \"复查指标录入位置已在病历中标注；当前关注“补录随访结论并确认处方用量”\"),\n    (\"ACT-250616-1487\", \"TASK-250616-044\", \"REFILL-20250616-ENDO\", \"CLINICIAN-CHEN-JINGHUI\", \"COMMENT\", \"2025-06-16 14:12:14\", \"OPEN\", \"OPEN\", \"药师补充说明本次续配审核关注事项；当前关注“补录随访结论并确认处方用量”\"),\n    (\"ACT-250616-3608\", \"TASK-250616-044\", \"REFILL-20250616-ENDO\", \"CLINICIAN-CHEN-JINGHUI\", \"COMMENT\", \"2025-06-16 14:43:07\", \"OPEN\", \"OPEN\", \"责任医师记录阶段性审核意见；当前关注“补录随访结论并确认处方用量”\"),\n    (\"ACT-250616-2565\", \"TASK-250616-044\", \"REFILL-20250616-ENDO\", \"CLINICIAN-ZHOU-NING\", \"COMMENT\", \"2025-06-16 17:07:19\", \"OPEN\", \"OPEN\", \"患者反馈近期病情及不良反应情况；当前关注“补录随访结论并确认处方用量”\"),\n    (\"ACT-250616-4306\", \"TASK-250616-044\", \"REFILL-20250616-ENDO\", \"CLINICIAN-XU-MAN\", \"COMMENT\", \"2025-06-16 17:09:35\", \"OPEN\", \"OPEN\", \"处方药品通用名、剂型和规格已复核；当前关注“补录随访结论并确认处方用量”\"),\n    (\"ACT-250616-5009\", \"TASK-250616-044\", \"REFILL-20250616-ENDO\", \"STAFF-LI-SHUNING\", \"COMMENT\", \"2025-06-16 17:14:26\", \"OPEN\", \"OPEN\", \"随访计划与本次拟续配天数完成比对；当前关注“补录随访结论并确认处方用量”\"),\n]\n\ndef _db_path(ws):\n    candidates = [ws.parent / \"system\" / \"seeyon_physician_tasks\" / \"state.db\", Path.cwd() / \"system\" / \"seeyon_physician_tasks\" / \"state.db\"]\n    for path in candidates:\n        if path.exists():\n            return path\n    raise FileNotFoundError(\"seeyon_physician_tasks state.db not found\")\n\ndef _hash_rows(connection, table, where_sql):\n    rows = [dict(row) for row in connection.execute(f\"SELECT * FROM {table} WHERE {where_sql} ORDER BY rowid\")]\n    payload = json.dumps(rows, ensure_ascii=False, sort_keys=True, separators=(\",\", \":\"))\n    return hashlib.sha256(payload.encode(\"utf-8\")).hexdigest()\n\ndef check_target_task(ws):\n    with sqlite3.connect(_db_path(ws)) as connection:\n        connection.row_factory = sqlite3.Row\n        row = connection.execute(\"SELECT task_id, assignee_id, priority, due_at, task_status FROM physician_task WHERE task_id = ?\", (TARGET,)).fetchone()\n    expected = (TARGET, \"CLINICIAN-ZHOU-NING\", \"HIGH\", \"2025-06-16 11:00:00\", \"OPEN\")\n    actual = tuple(row) if row else None\n    return {\"score\": 1 if actual == expected else 0, \"detail\": f\"target={actual}, expected={expected}\"}\n\ndef check_handoff_activity(ws):\n    with sqlite3.connect(_db_path(ws)) as connection:\n        connection.row_factory = sqlite3.Row\n        rows = connection.execute(\"SELECT activity_id, task_id, batch_id, actor_id, activity_type, activity_at, from_status, to_status, activity_text FROM task_activity WHERE task_id = ? ORDER BY activity_at, activity_id\", (TARGET,)).fetchall()\n    base_ok = all(tuple(row) in BASE_TARGET_ACTIVITY_ROWS for row in rows if row[4] != \"HANDOFF\")\n    handoffs = [row for row in rows if row[4] == \"HANDOFF\"]\n    valid = len(rows) == BASE_TARGET_ACTIVITY_COUNT + 1 and base_ok and len(handoffs) == 1\n    if valid:\n        row = handoffs[0]\n        text = row[8] or \"\"\n        valid = row[6] == \"OPEN\" and row[7] == \"OPEN\" and \"CLINICIAN-CHEN-JINGHUI\" in text and \"CLINICIAN-ZHOU-NING\" in text\n    return {\"score\": 1 if valid else 0, \"detail\": f\"target_activity_count={len(rows)}, handoffs={len(handoffs)}\"}\n\ndef check_no_unrelated_changes(ws):\n    with sqlite3.connect(_db_path(ws)) as connection:\n        connection.row_factory = sqlite3.Row\n        task_hash = _hash_rows(connection, \"physician_task\", \"task_id <> 'TASK-250616-044'\")\n        activity_hash = _hash_rows(connection, \"task_activity\", \"task_id <> 'TASK-250616-044'\")\n    valid = task_hash == NON_TARGET_TASK_HASH and activity_hash == NON_TARGET_ACTIVITY_HASH\n    return {\"score\": 1 if valid else 0, \"detail\": f\"tasks={task_hash}, activities={activity_hash}\"}\n",
